package com.nvv.mediadata.data.utilsimport kotlinx.serialization.KSerializerimport kotlinx.serialization.descriptors.PrimitiveKindimport kotlinx.serialization.descriptors.PrimitiveSerialDescriptorimport kotlinx.serialization.descriptors.SerialDescriptorimport kotlinx.serialization.encoding.Decoderimport kotlinx.serialization.encoding.Encoderimport java.time.LocalDateobject LocalDateSerializer : KSerializer<LocalDate?> {	override val descriptor: SerialDescriptor = PrimitiveSerialDescriptor("LocalDate", PrimitiveKind.STRING)	override fun deserialize(decoder: Decoder): LocalDate? {		val stringVal = decoder.decodeString()		if (stringVal.isEmpty()) {			return null		}		return try {			LocalDate.parse(stringVal)		} catch (e: Exception) {			e.printStackTrace()			null		}	}	override fun serialize(encoder: Encoder, value: LocalDate?) {		if (value != null) {			encoder.encodeString(value.toString())		} else {			encoder.encodeString("")		}	}}